// Company logos for the payslip header, keyed by platform slug. Embedded as
// base64 so they travel with the compiled code - a loose image file would not
// be copied by the build. A platform without an entry gets a text-only header.
// To add one: base64-encode a PNG and add a line to LOGOS.

const COLAB =
  "";

export const LOGOS: Record<string, Buffer> = {
  "colab-platforms-limited": Buffer.from(COLAB, "base64"),
};
